#!/usr/bin/env bun
// styles/breakpoints.css from components/Layout/layout.ts (#916): the same scale for CSS as for TypeScript.
// Opt-in (not in global.css): `@custom-media` needs a bundler that supports it (Lightning CSS with
// `drafts.customMedia`, PostCSS preset-env); browsers do not read it natively.
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { BREAKPOINTS } from "../src/lib/components/Layout/layout.ts";

const lines = [
	"/* Generated by scripts/build-breakpoints.ts from components/Layout/layout.ts: do not edit. Opt-in:",
	' *   @import "@codeatlasdev/ui/styles/breakpoints.css";   then  @media (--ca-md) { … }  /  @media (--ca-below-md) { … }',
	" * Needs @custom-media support in your bundler (Lightning CSS drafts.customMedia, PostCSS preset-env). */",
	...Object.entries(BREAKPOINTS).flatMap(([name, px]) => [
		`@custom-media --ca-${name} (min-width: ${px}px);`,
		`@custom-media --ca-below-${name} (max-width: ${px - 0.02}px);`,
	]),
	"",
];
writeFileSync(join(import.meta.dir, "../src/lib/styles/breakpoints.css"), lines.join("\n"));
